const e = $input.first().json;
// The Telegram node sends HTML: <, > and & in the error message (e.g. an HTML error page) would break sending.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clean = s => esc(String(s ?? '').replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').slice(0, 500));
const wf = esc(e.workflow?.name || 'nepoznat workflow');
const node = esc(e.execution?.lastNodeExecuted || '?');
const msg = clean(e.execution?.error?.message || e.trigger?.error?.message || 'bez poruke');
const id = e.execution?.id || '';

// Throttling: the same error (workflow + node + message) at most once per hour.
// Kept in this workflow's static data; n8n persists it only after production executions.
const HOUR = 60 * 60 * 1000;
const now = Date.now();
const store = $getWorkflowStaticData('global');
const alerts = {};
for (const [k, v] of Object.entries(store.alerts || {})) {
  if (now - v.sentAt < 24 * HOUR) alerts[k] = { sentAt: v.sentAt, suppressed: v.suppressed || 0 };
}
const key = `${e.workflow?.id || wf}|${node}|${msg.replace(/\d{4,}/g, '#').slice(0, 200)}`;
const prev = alerts[key];
if (prev && now - prev.sentAt < HOUR) {
  alerts[key] = { sentAt: prev.sentAt, suppressed: prev.suppressed + 1 };
  store.alerts = alerts;
  return [];
}
alerts[key] = { sentAt: now, suppressed: 0 };
store.alerts = alerts;

const repeat = prev && prev.suppressed > 0 ? `\n🔁 Od prošlog upozorenja ponovilo se još ${prev.suppressed}×` : '';
const when = new Date().toLocaleString('sr-RS', { timeZone: 'Europe/Belgrade' });
const text = `🚨 Stan Hunter: pukao workflow\n📦 ${wf}\n🔧 Node: ${node}\n💬 ${msg}${repeat}\n🆔 Execution: ${id}\n🕒 ${when}`;
return [{ json: { text } }];
